def pid_aw(errors, kp, ki, dt, lo, hi):
    # your code
    pass

practice.solution:
def pid_aw(errors, kp, ki, dt, lo, hi):
    integ = 0.0
    out = []
    for e in errors:
        trial = integ + e * dt
        raw = kp * e + ki * trial
        if lo <= raw <= hi:
            integ = trial
        u = kp * e + ki * integ
        if u < lo:
            u = lo
        if u > hi:
            u = hi
        out.append(round(u, 3))
    return out

